// Gold six has special art on issued tickets, their owned inventory chart cells,
// and confirmed main-jackpot displays.
// Generic badge builders must continue to return the ordinary die.
export const GOLD_SIX_TRAIT_ID = 253;
export const GOLD_SIX_MONKEY_BADGE = '/app/assets/jackpot/gold-six-monkey-v1.svg';

export function isGoldSix(quadrant, symbol, color) {
  return Number(quadrant) === 3 && Number(symbol) === 5 && Number(color) === 7;
}

/** Exclude gold six from cosmetic reel frames without changing a locked result. */
export function previewSpinTrait(quadrant, symbol, color, {
  symbolLocked = false,
  colorLocked = false,
} = {}) {
  if (!isGoldSix(quadrant, symbol, color) || (symbolLocked && colorLocked)) {
    return { sym: symbol, col: color };
  }
  // Preserve whichever axis has already locked. Never reroll in a loop: a
  // deterministic RNG (or a test fixture) must still be able to advance.
  return symbolLocked ? { sym: symbol, col: 6 } : { sym: 6, col: color };
}
